{"query": "-- Update Andrew Adams title to CEO
UPDATE "Employee" SET "Title" = 'CEO' WHERE "EmployeeId" = 1;

-- Update Nancy Edwards phone number
UPDATE "Employee" SET "Phone" = '+1 (403) 555-9999' WHERE "EmployeeId" = 2;

-- Change all IT Staff to IT Specialist
UPDATE "Employee" SET "Title" = 'IT Specialist' WHERE "Title" = 'IT Staff';"}

{"query": "-- Reassign customers 1, 2, 3 to Sarah Johnson (EmployeeId=9)
UPDATE "Customer" SET "SupportRepId" = 9 WHERE "CustomerId" IN (1, 2, 3);

-- Reassign customers 4, 5, 6 to Mike Chen (EmployeeId=10)
UPDATE "Customer" SET "SupportRepId" = 10 WHERE "CustomerId" IN (4, 5, 6);"}

{"query": "-- Change Sarah Johnson (9) to report to Andrew Adams (1)
UPDATE "Employee" SET "ReportsTo" = 1 WHERE "EmployeeId" = 9;

-- Change Mike Chen (10) to report to Andrew Adams (1)
UPDATE "Employee" SET "ReportsTo" = 1 WHERE "EmployeeId" = 10;"}

{"query": "-- Check if any employees report to Robert King (7)
SELECT "EmployeeId", "FirstName", "LastName", "ReportsTo" FROM "Employee" WHERE "ReportsTo" = 7;

-- Check if any customers are assigned to Robert King (7)
SELECT COUNT(*) as customer_count FROM "Customer" WHERE "SupportRepId" = 7;"}

{"query": "-- Add salary column to Employee table
ALTER TABLE "Employee" ADD COLUMN IF NOT EXISTS "salary" DECIMAL;

-- Promote Laura Callahan (8) to Senior IT Specialist
UPDATE "Employee" SET "Title" = 'Senior IT Specialist' WHERE "EmployeeId" = 8;

-- Set Laura's salary to 75000.00
UPDATE "Employee" SET "salary" = 75000.00 WHERE "EmployeeId" = 8;

-- Set all other employees' salary to 50000.00
UPDATE "Employee" SET "salary" = 50000.00 WHERE "EmployeeId" != 8;"}
